#include "simp/SemanticAnalyzer.hpp"

#include "simp/Diagnostic.hpp"

#include <charconv>
#include <cstdint>
#include <ostream>
#include <string>

namespace simp {

const char* valueTypeName(ValueType type) noexcept {
    return type == ValueType::Integer ? "int" : "string";
}

void SemanticAnalyzer::analyze(const Program& program) {
    scopes_.clear();
    symbols_.clear();
    scopes_.emplace_back();
    analyzeStatements(program.statements);
}

std::size_t SemanticAnalyzer::findSymbol(const std::string& name,
                                         const SourceLocation& location) const {
    for (auto scope = scopes_.rbegin(); scope != scopes_.rend(); ++scope) {
        const auto found = scope->find(name);
        if (found != scope->end()) {
            const auto index = found->second;
            if (!symbols_[index].initialized) {
                throw DiagnosticError(location, "variable '" + name + "' may be uninitialized");
            }
            return index;
        }
    }
    throw DiagnosticError(location, "undefined variable '" + name + "'");
}

ValueType SemanticAnalyzer::analyzeExpression(const Expression& expression) {
    switch (expression.kind) {
    case ExpressionKind::Integer: {
        std::int32_t value = 0;
        const auto* begin = expression.value.data();
        const auto* end = begin + expression.value.size();
        const auto parsed = std::from_chars(begin, end, value);
        if (parsed.ec != std::errc{} || parsed.ptr != end) {
            throw DiagnosticError(expression.location, "integer literal is outside the signed 32-bit range");
        }
        return ValueType::Integer;
    }
    case ExpressionKind::String:
        return ValueType::String;
    case ExpressionKind::Identifier:
        return symbols_[findSymbol(expression.value, expression.location)].type;
    case ExpressionKind::Unary: {
        if (analyzeExpression(*expression.left) != ValueType::Integer) {
            throw DiagnosticError(expression.location, "unary operator requires an int operand");
        }
        return ValueType::Integer;
    }
    case ExpressionKind::Binary: {
        const auto left = analyzeExpression(*expression.left);
        const auto right = analyzeExpression(*expression.right);
        const auto& operation = expression.value;
        if (operation == "==" || operation == "!=") {
            if (left != right) {
                throw DiagnosticError(expression.location,
                                      "comparison operands must have the same type");
            }
            return ValueType::Integer;
        }
        if (operation == "<" || operation == "<=" || operation == ">" ||
            operation == ">=" || operation == "+" || operation == "-" ||
            operation == "*" || operation == "/" || operation == "%") {
            if (left != ValueType::Integer || right != ValueType::Integer) {
                throw DiagnosticError(expression.location,
                                      "operator '" + operation + "' requires int operands");
            }
            return ValueType::Integer;
        }
        throw DiagnosticError(expression.location, "unsupported binary operator '" + operation + "'");
    }
    }
    throw DiagnosticError(expression.location, "invalid expression");
}

void SemanticAnalyzer::analyzeStatements(const std::vector<Statement>& statements) {
    for (const auto& statement : statements) {
        analyzeStatement(statement);
    }
}

std::vector<bool> SemanticAnalyzer::initializationState() const {
    std::vector<bool> state;
    state.reserve(symbols_.size());
    for (const auto& symbol : symbols_) {
        state.push_back(symbol.initialized);
    }
    return state;
}

void SemanticAnalyzer::restoreInitializationState(const std::vector<bool>& state) {
    for (std::size_t index = 0; index < state.size(); ++index) {
        symbols_[index].initialized = state[index];
    }
}

void SemanticAnalyzer::analyzeStatement(const Statement& statement) {
    switch (statement.kind) {
    case StatementKind::Declaration: {
        auto& scope = scopes_.back();
        if (scope.find(statement.name) != scope.end()) {
            throw DiagnosticError(statement.location,
                                  "variable '" + statement.name + "' is already declared in this scope");
        }
        const auto type = statement.declaredType == "int" ? ValueType::Integer : ValueType::String;
        const auto index = symbols_.size();
        symbols_.push_back({statement.name, type, false, statement.location});
        scope.emplace(statement.name, index);
        if (!statement.expressions.empty()) {
            const auto initializerType = analyzeExpression(*statement.expressions.front());
            if (initializerType != type) {
                throw DiagnosticError(statement.expressions.front()->location,
                                      "cannot initialize " + std::string(valueTypeName(type)) +
                                          " variable with " + valueTypeName(initializerType));
            }
            symbols_[index].initialized = true;
        }
        return;
    }
    case StatementKind::Assignment: {
        std::size_t index = 0;
        bool foundSymbol = false;
        for (auto scope = scopes_.rbegin(); scope != scopes_.rend(); ++scope) {
            const auto found = scope->find(statement.name);
            if (found != scope->end()) {
                index = found->second;
                foundSymbol = true;
                break;
            }
        }
        if (!foundSymbol) {
            throw DiagnosticError(statement.location, "undefined variable '" + statement.name + "'");
        }
        const auto assignedType = analyzeExpression(*statement.expressions.front());
        const auto declaredType = symbols_[index].type;
        if (assignedType != declaredType) {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "cannot assign " + std::string(valueTypeName(assignedType)) +
                                      " to " + valueTypeName(declaredType) + " variable '" +
                                      statement.name + "'");
        }
        symbols_[index].initialized = true;
        return;
    }
    case StatementKind::Print: {
        std::vector<ValueType> types;
        types.reserve(statement.expressions.size());
        for (const auto& expression : statement.expressions) {
            types.push_back(analyzeExpression(*expression));
        }
        if (types.size() > 1) {
            const auto& format = *statement.expressions.front();
            if (types.front() != ValueType::String ||
                (format.kind == ExpressionKind::String && !format.formattedString)) {
                throw DiagnosticError(format.location,
                                      "multiple print values require a double-quoted format string");
            }
        }
        return;
    }
    case StatementKind::If: {
        if (analyzeExpression(*statement.expressions.front()) != ValueType::Integer) {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "if condition must have type int");
        }
        const auto before = initializationState();
        scopes_.emplace_back();
        analyzeStatements(statement.body);
        scopes_.pop_back();
        const auto thenState = initializationState();
        if (!statement.hasAlternate) {
            restoreInitializationState(before);
            return;
        }
        restoreInitializationState(before);
        scopes_.emplace_back();
        analyzeStatements(statement.alternate);
        scopes_.pop_back();
        const auto elseState = initializationState();
        for (std::size_t index = 0; index < before.size(); ++index) {
            symbols_[index].initialized = thenState[index] && elseState[index];
        }
        return;
    }
    case StatementKind::While: {
        if (analyzeExpression(*statement.expressions.front()) != ValueType::Integer) {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "while condition must have type int");
        }
        const auto before = initializationState();
        scopes_.emplace_back();
        analyzeStatements(statement.body);
        scopes_.pop_back();
        restoreInitializationState(before);
        return;
    }
    case StatementKind::Block:
        scopes_.emplace_back();
        analyzeStatements(statement.body);
        scopes_.pop_back();
        return;
    }
}

void SemanticAnalyzer::dumpSymbolTable(std::ostream& output) const {
    output << "Symbols:\n";
    for (const auto& symbol : symbols_) {
        output << "  " << valueTypeName(symbol.type) << " " << symbol.name << " ("
               << (symbol.initialized ? "initialized" : "uninitialized") << ") at "
               << symbol.location.line << ":" << symbol.location.column << '\n';
    }
}

} // namespace simp
